<script setup>
import { onMounted, reactive, ref } from 'vue';
import DataTable from 'primevue/datatable';
import Column from 'primevue/column';
import Paginator from 'primevue/paginator';
import Dialog from 'primevue/dialog';
import Dropdown from 'primevue/dropdown';
import InputText from 'primevue/inputtext';
import Textarea from 'primevue/textarea';
import apiClient from '../services/apiClient';
import { createLogger, logException } from '../utils/logger';

const logger = createLogger('AdminAllAds');
const ads = ref([]); const banks = ref([]); const loading = ref(false); const acting = ref(false); const error = ref('');
const search = ref(''); const status = ref(null); const bankId = ref(null); const type = ref(null); const amountRange = ref(null);
const meta = ref({ current_page: 1, total: 0, per_page: 10 }); const selectedAd = ref(null); const editingAd = ref(null); const deleteTarget = ref(null); const rejectTarget = ref(null); const rejectionReason = ref('');
const editForm = reactive({ title: '', description: '', type: 'supply', bank_id: null, bank_plan_id: null, loan_amount: '', assignment_price: '', profit_rate: '', installment_count: '' });
const statusOptions = [{ label: 'همه وضعیت‌ها', value: null }, { label: 'در انتظار بررسی', value: 'pending_approval' }, { label: 'منتشرشده', value: 'published' }, { label: 'ردشده', value: 'rejected' }, { label: 'منقضی‌شده', value: 'expired' }, { label: 'حذف‌شده', value: 'deleted' }];
const typeOptions = [{ label: 'همه انواع', value: null }, { label: 'واگذاری امتیاز', value: 'supply' }, { label: 'تقاضای خرید', value: 'demand' }];
const amountOptions = [{ label: 'همه مبالغ', value: null }, { label: 'زیر ۵۰ میلیون', value: 'under_50' }, { label: '۵۰ تا ۲۰۰ میلیون', value: '50_200' }, { label: 'بالای ۲۰۰ میلیون', value: 'over_200' }];
const statusLabels = { pending: 'در انتظار بررسی', pending_approval: 'در انتظار بررسی', published: 'منتشرشده', approved: 'منتشرشده', rejected: 'ردشده', expired: 'منقضی‌شده', handed_over: 'واگذارشده', closed: 'بسته‌شده' };

function statusLabel(ad) { return ad.deleted_at ? 'حذف‌شده' : statusLabels[ad.status] || ad.status || '-'; }
function statusClass(ad) { return ad.deleted_at ? 'status-deleted' : `status-${ad.status}`; }
function typeLabel(value) { return value === 'demand' ? 'تقاضای خرید' : 'واگذاری امتیاز'; }
function money(value) { return value ? `${new Intl.NumberFormat('fa-IR').format(value)} تومان` : '-'; }
function date(value) { return value ? new Intl.DateTimeFormat('fa-IR', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '-'; }
function resetEdit(ad) { Object.assign(editForm, { title: ad.title || '', description: ad.description || '', type: ad.type || 'supply', bank_id: ad.bank_id || ad.bank?.id || null, bank_plan_id: ad.bank_plan_id || ad.bankPlan?.id || null, loan_amount: ad.loan_amount || '', assignment_price: ad.assignment_price || '', profit_rate: ad.profit_rate || '', installment_count: ad.installment_count || '' }); }

async function load(page = 1) {
    loading.value = true; error.value = '';
    try {
        const [adsResponse, banksResponse] = await Promise.all([
            apiClient.get('/admin/ads/all', { params: { search: search.value || undefined, status: status.value || undefined, bank_id: bankId.value || undefined, type: type.value || undefined, amount_range: amountRange.value || undefined, page, per_page: 10 } }),
            banks.value.length ? Promise.resolve({ data: { data: banks.value } }) : apiClient.get('/banks'),
        ]);
        ads.value = adsResponse.data.data || []; meta.value = adsResponse.data.meta || meta.value; banks.value = banks.value.length ? banks.value : (banksResponse.data.data || banksResponse.data || []);
        logger.info('load', 'All advertisements loaded', { count: ads.value.length, total: meta.value.total });
    } catch (exception) { error.value = 'دریافت آرشیو آگهی‌ها انجام نشد.'; logger.error('load', 'All advertisements failed', logException(exception)); }
    finally { loading.value = false; }
}
function clearFilters() { search.value = ''; status.value = null; bankId.value = null; type.value = null; amountRange.value = null; load(1); }
function openEdit(ad) { editingAd.value = ad; resetEdit(ad); }
function closeEdit() { editingAd.value = null; }
async function saveEdit() { if (!editingAd.value) return; acting.value = true; try { const { data } = await apiClient.put(`/admin/ads/${editingAd.value.id}`, { ...editForm }); const index = ads.value.findIndex((ad) => ad.id === editingAd.value.id); if (index >= 0) ads.value[index] = data.data; closeEdit(); } catch (exception) { error.value = 'ویرایش آگهی انجام نشد.'; logger.error('saveEdit', 'Advertisement update failed', logException(exception)); } finally { acting.value = false; } }
async function setStatus(ad, nextStatus, reason = null) { acting.value = true; try { const { data } = await apiClient.patch(`/admin/ads/${ad.id}/status`, { status: nextStatus, rejection_reason: reason || undefined }); replaceAd(data.data); } catch (exception) { error.value = 'تغییر وضعیت آگهی انجام نشد.'; logger.error('setStatus', 'Advertisement status change failed', logException(exception)); } finally { acting.value = false; } }
async function approve(ad) { await setStatus(ad, 'published'); }
async function reject() { if (!rejectTarget.value || !rejectionReason.value.trim()) return; await setStatus(rejectTarget.value, 'rejected', rejectionReason.value); rejectTarget.value = null; rejectionReason.value = ''; }
async function removeAd() { if (!deleteTarget.value) return; acting.value = true; try { await apiClient.delete(`/admin/ads/${deleteTarget.value.id}`); ads.value = ads.value.filter((ad) => ad.id !== deleteTarget.value.id); meta.value.total = Math.max(0, meta.value.total - 1); deleteTarget.value = null; } catch (exception) { error.value = 'بایگانی آگهی انجام نشد.'; logger.error('removeAd', 'Advertisement deletion failed', logException(exception)); } finally { acting.value = false; } }
function replaceAd(updated) { const index = ads.value.findIndex((ad) => ad.id === updated.id); if (index >= 0) ads.value[index] = { ...ads.value[index], ...updated }; }
onMounted(load);
</script>

<template>
    <section class="all-ads-page" dir="rtl">
        <header class="all-ads-header"><div><span>مدیریت سامانه / آرشیو آگهی‌ها</span><h1>مدیریت جامع آگهی‌ها</h1><p>تمام آگهی‌های سامانه را جست‌وجو، ویرایش و کنترل کنید.</p></div><b class="archive-count">{{ meta.total }} آگهی</b></header>
        <p v-if="error" class="all-ads-error" role="alert"><i class="pi pi-exclamation-triangle"></i>{{ error }}</p>
        <div class="all-ads-toolbar"><div class="toolbar-title"><span><i class="pi pi-sliders-h"></i>کنترل آرشیو</span><strong>فیلترهای پیشرفته</strong></div><div class="smart-search"><label for="all-ads-search">جست‌وجوی آگهی</label><span><i class="pi pi-search"></i><InputText id="all-ads-search" v-model="search" placeholder="عنوان، کد یا موبایل کاربر" @keyup.enter="load(1)" /></span></div><div class="filter-field"><label>وضعیت انتشار</label><Dropdown v-model="status" :options="statusOptions" optionLabel="label" optionValue="value" class="filter-select" panelClass="all-ads-panel" /></div><div class="filter-field"><label>بانک عامل</label><Dropdown v-model="bankId" :options="[{ id: null, name: 'همه بانک‌ها' }, ...banks]" optionLabel="name" optionValue="id" class="filter-select" panelClass="all-ads-panel" /></div><div class="filter-field"><label>نوع معامله</label><Dropdown v-model="type" :options="typeOptions" optionLabel="label" optionValue="value" class="filter-select" panelClass="all-ads-panel" /></div><div class="filter-field"><label>محدوده مبلغ</label><Dropdown v-model="amountRange" :options="amountOptions" optionLabel="label" optionValue="value" class="filter-select" panelClass="all-ads-panel" /></div><button class="clear-button" type="button" @click="clearFilters"><i class="pi pi-filter-slash"></i>پاک‌سازی</button><button class="apply-button" type="button" @click="load(1)"><i class="pi pi-search"></i>اعمال فیلتر</button></div>
        <div class="all-ads-table"><DataTable :value="ads" dataKey="id" :loading="loading" stripedRows responsiveLayout="scroll"><Column field="id" header="کد" /><Column header="عنوان آگهی"><template #body="slotProps"><strong class="ad-title">{{ slotProps.data.title }}</strong><small class="ad-description">{{ slotProps.data.description || 'بدون توضیحات' }}</small></template></Column><Column header="ثبت‌کننده"><template #body="slotProps"><strong>{{ slotProps.data.user?.name || '-' }}</strong><small class="user-mobile">{{ slotProps.data.user?.mobile || '-' }}</small></template></Column><Column header="بانک"><template #body="slotProps">{{ slotProps.data.bank?.name || '-' }}</template></Column><Column header="مبلغ وام"><template #body="slotProps">{{ money(slotProps.data.loan_amount) }}</template></Column><Column header="وضعیت"><template #body="slotProps"><span class="status-pill" :class="statusClass(slotProps.data)">{{ statusLabel(slotProps.data) }}</span></template></Column><Column header="تاریخ ثبت"><template #body="slotProps">{{ date(slotProps.data.created_at) }}</template></Column><Column header="عملیات" style="min-width: 180px"><template #body="slotProps"><div class="action-list"><button type="button" title="مشاهده جزئیات" @click="selectedAd = slotProps.data"><i class="pi pi-eye"></i></button><button type="button" title="ویرایش" @click="openEdit(slotProps.data)"><i class="pi pi-pencil"></i></button><button v-if="!slotProps.data.deleted_at" type="button" title="انتشار" @click="approve(slotProps.data)"><i class="pi pi-check"></i></button><button v-if="!slotProps.data.deleted_at" type="button" title="رد آگهی" @click="rejectTarget = slotProps.data"><i class="pi pi-times"></i></button><button v-if="!slotProps.data.deleted_at" type="button" class="danger" title="حذف منطقی" @click="deleteTarget = slotProps.data"><i class="pi pi-trash"></i></button></div></template></Column><template #empty><div class="empty-state"><i class="pi pi-folder-open"></i><p>آگهی‌ای با این فیلترها پیدا نشد.</p></div></template></DataTable><footer class="table-footer"><span>نمایش {{ ads.length }} آگهی از {{ meta.total }} آگهی</span><Paginator :first="(meta.current_page - 1) * meta.per_page" :rows="meta.per_page" :totalRecords="meta.total" :rowsPerPageOptions="[10]" @page="load($event.page + 1)" /></footer></div>
        <Dialog v-model:visible="selectedAd" modal header="جزئیات جامع آگهی" class="all-ads-dialog" :style="{ width: 'min(720px, 94vw)' }"><div v-if="selectedAd" class="details-grid"><div><small>عنوان</small><strong>{{ selectedAd.title }}</strong></div><div><small>وضعیت فعلی</small><strong>{{ statusLabel(selectedAd) }}</strong></div><div><small>ثبت‌کننده</small><strong>{{ selectedAd.user?.name || '-' }} / {{ selectedAd.user?.mobile || '-' }}</strong></div><div><small>بانک و نوع</small><strong>{{ selectedAd.bank?.name || '-' }} / {{ typeLabel(selectedAd.type) }}</strong></div><div><small>مبلغ وام</small><strong>{{ money(selectedAd.loan_amount) }}</strong></div><div><small>قیمت واگذاری</small><strong>{{ money(selectedAd.assignment_price) }}</strong></div><div class="wide"><small>توضیحات</small><p>{{ selectedAd.description || 'بدون توضیحات' }}</p></div><div class="wide history-box"><small>تاریخچه وضعیت</small><p>ثبت اولیه: {{ date(selectedAd.created_at) }}</p><p>آخرین بروزرسانی: {{ date(selectedAd.updated_at) }}</p><p>وضعیت فعلی: {{ statusLabel(selectedAd) }}</p></div></div></Dialog>
        <Dialog v-model:visible="editingAd" modal header="ویرایش آگهی" class="all-ads-dialog" :style="{ width: 'min(720px, 94vw)' }"><form class="edit-form" @submit.prevent="saveEdit"><label>عنوان آگهی<InputText v-model="editForm.title" required /></label><label>نوع معامله<Dropdown v-model="editForm.type" :options="typeOptions.slice(1)" optionLabel="label" optionValue="value" /></label><label>مبلغ وام<InputText v-model="editForm.loan_amount" inputmode="numeric" /></label><label>قیمت واگذاری<InputText v-model="editForm.assignment_price" inputmode="numeric" /></label><label class="wide">توضیحات<Textarea v-model="editForm.description" rows="5" autoResize /></label><div class="form-actions"><button type="button" class="clear-button" @click="closeEdit">انصراف</button><button type="submit" class="apply-button" :disabled="acting">ذخیره تغییرات</button></div></form></Dialog>
        <Dialog v-model:visible="rejectTarget" modal header="رد آگهی" :style="{ width: 'min(450px, 94vw)' }"><div class="confirm-content"><p>علت رد «{{ rejectTarget?.title }}» را وارد کنید.</p><Textarea v-model="rejectionReason" rows="4" autoResize placeholder="دلیل رد آگهی" /><button class="reject-button" type="button" :disabled="acting || !rejectionReason.trim()" @click="reject">ثبت رد آگهی</button></div></Dialog>
        <Dialog v-model:visible="deleteTarget" modal header="بایگانی آگهی" :style="{ width: 'min(430px, 94vw)' }"><div class="confirm-content"><i class="pi pi-trash warning-icon"></i><p>آگهی «{{ deleteTarget?.title }}» از لیست عمومی حذف و بایگانی شود؟</p><div class="form-actions"><button type="button" class="clear-button" @click="deleteTarget = null">انصراف</button><button type="button" class="reject-button" :disabled="acting" @click="removeAd">حذف منطقی</button></div></div></Dialog>
    </section>
</template>

<style scoped>
.all-ads-page { max-width: 1500px; margin: 0 auto; }.all-ads-header { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 24px; }.all-ads-header span { color: #a62626; font-size: 10px; }.all-ads-header h1 { margin: 7px 0 4px; color: #0f172a; font-size: 26px; }.all-ads-header p { margin: 0; color: #64748b; font-size: 12px; }.archive-count { padding: 9px 13px; border-radius: 999px; background: #fff1f2; color: #a62626; font-size: 11px; }.all-ads-error { display: flex; gap: 8px; margin-bottom: 14px; padding: 11px; background: #fef2f2; color: #b91c1c; font-size: 11px; }.all-ads-toolbar { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 12px; margin-bottom: 22px; padding: 16px; border: 1px solid #e2e8f0; border-radius: 16px; background: #fff; box-shadow: 0 4px 14px #0f172a0f; }.toolbar-title { display: grid; min-width: 140px; gap: 4px; margin-left: auto; }.toolbar-title span, .filter-field label, .smart-search label { color: #64748b; font-size: 10px; font-weight: 800; }.toolbar-title span { color: #a62626; }.toolbar-title strong { color: #0f172a; font-size: 13px; }.smart-search, .filter-field { display: grid; min-width: 155px; gap: 6px; }.smart-search { min-width: 250px; flex: 1 1 260px; }.smart-search > span { display: flex; align-items: center; gap: 8px; min-height: 42px; padding: 0 12px; border: 1px solid #cbd5e1; border-radius: 12px; color: #94a3b8; }.smart-search > span:focus-within { border-color: #a62626; box-shadow: 0 0 0 3px #fee2e2; }.smart-search :deep(.p-inputtext) { width: 100%; padding: 10px 0; border: 0; outline: 0; box-shadow: none; font: inherit; font-size: 11px; }.filter-select { min-height: 42px; border: 1px solid #cbd5e1; border-radius: 12px; background: #fff; }.filter-select :deep(.p-dropdown-label), .filter-select :deep(.p-select-label) { padding: 11px 12px; font-size: 10px; }.clear-button, .apply-button, .reject-button { display: inline-flex; min-height: 42px; align-items: center; justify-content: center; gap: 6px; padding: 10px 15px; border-radius: 11px; cursor: pointer; font: inherit; font-size: 10px; font-weight: 800; }.clear-button { border: 1px solid #cbd5e1; background: #f8fafc; color: #475569; }.apply-button { border: 1px solid #a62626; background: #a62626; color: #fff; }.reject-button { border: 0; background: #b91c1c; color: #fff; }.all-ads-table { overflow: hidden; border: 1px solid #e2e8f0; border-radius: 16px; background: #fff; box-shadow: 0 3px 12px #0f172a0a; }.all-ads-table :deep(.p-datatable) { font-size: 11px; }.all-ads-table :deep(th) { padding: 14px; background: #f8fafc; color: #334155; font-size: 10px; text-align: right; }.all-ads-table :deep(td) { padding: 13px 14px; color: #475569; vertical-align: middle; }.ad-title, .ad-description, .user-mobile { display: block; }.ad-title { color: #1e293b; font-size: 11px; }.ad-description, .user-mobile { margin-top: 4px; color: #94a3b8; font-size: 9px; }.status-pill { display: inline-flex; padding: 5px 8px; border-radius: 999px; font-size: 9px; font-weight: 800; white-space: nowrap; }.status-published, .status-approved { background: #dcfce7; color: #15803d; }.status-pending, .status-pending_approval { background: #fef3c7; color: #a16207; }.status-rejected { background: #fee2e2; color: #b91c1c; }.status-expired, .status-closed { background: #e2e8f0; color: #475569; }.status-deleted { background: #f1f5f9; color: #64748b; }.action-list { display: flex; gap: 5px; }.action-list button { display: grid; width: 30px; height: 30px; place-items: center; border: 0; border-radius: 8px; background: #f1f5f9; color: #475569; cursor: pointer; }.action-list button:hover { background: #fee2e2; color: #a62626; }.action-list button.danger { background: #fee2e2; color: #dc2626; }.table-footer { display: flex; align-items: center; justify-content: space-between; padding: 9px 14px; color: #64748b; font-size: 10px; }.table-footer :deep(.p-paginator) { justify-content: flex-start; direction: rtl; }.empty-state { padding: 55px; color: #94a3b8; text-align: center; }.empty-state i { font-size: 34px; }.details-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }.details-grid > div { padding: 12px; border-radius: 10px; background: #f8fafc; }.details-grid small { display: block; color: #94a3b8; font-size: 9px; }.details-grid strong { display: block; margin-top: 5px; color: #334155; font-size: 11px; line-height: 1.8; }.details-grid .wide, .edit-form .wide { grid-column: 1 / -1; }.details-grid p { margin: 6px 0 0; color: #475569; font-size: 11px; line-height: 1.9; }.history-box { border-right: 3px solid #a62626; }.edit-form { display: grid; grid-template-columns: repeat(2, 1fr); gap: 13px; }.edit-form label { display: grid; gap: 6px; color: #475569; font-size: 10px; font-weight: 800; }.edit-form :deep(.p-inputtext), .edit-form :deep(.p-inputtextarea), .edit-form :deep(.p-dropdown) { width: 100%; }.form-actions { display: flex; justify-content: flex-start; gap: 8px; margin-top: 5px; }.confirm-content { display: grid; gap: 14px; color: #475569; font-size: 12px; }.confirm-content p { margin: 0; line-height: 1.9; }.warning-icon { color: #dc2626; font-size: 30px; text-align: center; }@media (max-width: 900px) { .toolbar-title { width: 100%; margin-left: 0; }.filter-field { flex: 1 1 180px; }.smart-search { flex-basis: 100%; } }@media (max-width: 600px) { .all-ads-header { align-items: flex-start; flex-direction: column; gap: 12px; }.all-ads-toolbar { align-items: stretch; }.filter-field, .smart-search { width: 100%; min-width: 0; flex-basis: 100%; }.clear-button, .apply-button { width: 100%; }.details-grid, .edit-form { grid-template-columns: 1fr; }.details-grid .wide, .edit-form .wide { grid-column: auto; }}
</style>
